"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, Iterator, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _outside(span: Span, hours: Span) -> bool:
    early = span.start < hours.start
    return early or span.end > hours.end


def _check_inside(worked: Iterable[Span], opening: Span):
    for span in worked:
        if _outside(span, opening):
            text = format_span(span)
            raise ValueError(f"{text} is outside opening")


def _uncovered(
    merged: List[Span], opening: Span
) -> Iterator[Span]:
    cursor = opening.start
    for span in merged:
        if span.start > cursor:
            yield Span(cursor, span.start)
        cursor = span.end
    if cursor < opening.end:
        yield Span(cursor, opening.end)


def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"


# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """Labels like 'gap 12:00-13:00 (60 min)'."""
    spans = list(worked)
    _check_inside(spans, opening)
    merged = merge_spans(spans)
    gaps = _uncovered(merged, opening)
    return [_label(gap) for gap in gaps]

