# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")


class FindGapsTests(unittest.TestCase):
    def test_lunch_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        worked = [Span(540, 800), Span(700, 1020)]
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_edges_and_order(self):
        worked = [Span(900, 960), Span(600, 660)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-15:00 (240 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_touching_spans_leave_no_gap(self):
        worked = [Span(540, 700), Span(700, 1020)]
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_starts_before_opening(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], OPEN)

    def test_ends_after_opening(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(960, 1080)], OPEN)


if __name__ == "__main__":
    unittest.main()
